from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    Apply the first matching rewrite rule to each URL.

    Returns a list containing rewritten URLs, unchanged URLs, or None for
    blocked URLs.
    """

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower().rstrip(".")
        match_value = match_value.lower().rstrip(".")

        if match_value.startswith("*."):
            base_domain = match_value[2:]
            return (
                host != base_domain
                and host.endswith("." + base_domain)
            )

        return host == match_value

    def replace_host(parts, new_host):
        # Preserve user information and the original port.
        netloc = parts.netloc

        userinfo = ""
        host_port = netloc
        if "@" in netloc:
            userinfo, host_port = netloc.rsplit("@", 1)
            userinfo += "@"

        # Preserve the port, including for IPv6 addresses.
        port = ""
        if host_port.startswith("["):
            closing_bracket = host_port.find("]")
            if closing_bracket != -1:
                remainder = host_port[closing_bracket + 1:]
                if remainder.startswith(":"):
                    port = remainder
        elif ":" in host_port:
            _, possible_port = host_port.rsplit(":", 1)
            if possible_port:
                port = ":" + possible_port

        # Bracket IPv6 replacement hosts when necessary.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = f"{userinfo}{new_host}{port}"
        return parts._replace(netloc=new_netloc)

    results = []

    for url in urls:
        parts = urlsplit(url)
        rewritten_url = url

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            matched = False

            if match_type == "path_prefix":
                matched = parts.path.startswith(match_value)

            elif match_type == "host":
                matched = host_matches(parts.hostname, match_value)

            elif match_type == "query_param":
                query_params = parse_qsl(
                    parts.query,
                    keep_blank_values=True
                )
                matched = any(
                    name == match_value
                    for name, _ in query_params
                )

            if not matched:
                continue

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                prefix = rule["action_value"]
                new_path = parts.path

                if new_path.startswith(prefix):
                    new_path = new_path[len(prefix):]

                if not new_path:
                    new_path = "/"

                rewritten_url = urlunsplit(parts._replace(path=new_path))

            elif action == "redirect_host":
                rewritten_url = urlunsplit(
                    replace_host(parts, rule["action_value"])
                )

            elif action == "add_query_param":
                addition = rule["action_value"]
                new_query = (
                    f"{parts.query}&{addition}"
                    if parts.query
                    else addition
                )
                rewritten_url = urlunsplit(
                    parts._replace(query=new_query)
                )

            # Only the first matching rule is applied.
            break

        results.append(rewritten_url)

    return results
